import { EFFORT_LEVELS, type Effort, effectiveModels, loadConfig } from "./config.ts";
import { trace } from "./diagnostics.ts";
import { DEFAULT_MAX_TOKENS, type ChatMessage, type DeltaChannel, type Usage, chat } from "./groq.ts";
import { logger } from "./logger.ts";
import { costFromBreakdown, costFromUsage } from "./pricing.ts";
import { buildSystemPrompt } from "./prompts.ts";
import { formatToolResults, parseToolCalls, stripToolBlocks } from "./protocol.ts";
import { type ApprovalRequest, type TodoItem, buildTools, executeTool, isSafeBash } from "./tools.ts";

export interface AgentCallbacks {
  onDelta?: (text: string, channel: DeltaChannel) => void;
  onAssistantText?: (text: string) => void;
  onToolStart?: (tool: string, args: Record<string, unknown>) => void;
  onToolEnd?: (tool: string, status: "ok" | "error", output: string) => void;
  onApproval?: (req: ApprovalRequest) => Promise<boolean>;
  onUsage?: (usage: Usage, cost: number) => void;
  onNotice?: (text: string) => void;
  onTodos?: (todos: TodoItem[]) => void;
}

export interface AgentState {
  messages: ChatMessage[];
  totalUsage: Usage;
  lastPromptTokens: number;
}

export function newAgentState(): AgentState {
  return {
    messages: [],
    totalUsage: { prompt_tokens: 0, completion_tokens: 0, total_tokens: 0 },
    lastPromptTokens: 0,
  };
}

function addUsage(state: AgentState, usage: Usage): void {
  state.totalUsage.prompt_tokens += usage.prompt_tokens;
  state.totalUsage.completion_tokens += usage.completion_tokens;
  state.totalUsage.total_tokens += usage.total_tokens;
  state.lastPromptTokens = usage.prompt_tokens;
}

const ACTION_CLAIM_RE =
  /\b(?:I (?:created|wrote|ran|executed|made|added|updated|edited|installed|saved|built|recorded)|(?:has|have) been (?:created|written|executed|run|made|updated|edited|saved|built|recorded|noted|remembered)|was (?:created|written|executed|run|made|updated|edited|saved|built|recorded)|successfully (?:created|wrote|written|ran|executed|updated|built|saved)|script has|file now contains|the output (?:is|was)|tests?\s+(?:now\s+)?(?:all\s+)?pass|all tests pass)/i;

function claimsAction(text: string): boolean {
  return ACTION_CLAIM_RE.test(text);
}

const SUCCESS_CLAIM_RE =
  /\b(?:all tests pass|tests?\s+(?:now\s+)?(?:all\s+)?pass(?:es|ed)?|task is (?:now )?(?:complete|done)|successfully|works as (?:expected|intended|requested)|is (?:now )?(?:complete|fixed|working|resolved))\b/i;

function claimsSuccess(text: string): boolean {
  return SUCCESS_CLAIM_RE.test(text);
}

const GUESSED_CONTENT_RE =
  /\b(?:illustrative|typical contents?|likely (?:contains?|stored|located|holds?|lives|includes?)|presumably|probably (?:contains?|holds?|has|includes?)|based on (?:naming|common) (?:conventions?|patterns?)|might look (?:like|similar)|would typically|\(presumed?\b|common patterns\))/i;

function looksGuessed(text: string): boolean {
  return GUESSED_CONTENT_RE.test(text);
}

function approvalSummary(tool: string, args: Record<string, unknown>): ApprovalRequest {
  if (tool === "bash") {
    const cmd = String(args.command ?? "");
    return { tool, summary: "Run shell command", detail: cmd };
  }
  if (tool === "write_file") {
    const content = String(args.content ?? "");
    const preview = content.split("\n").slice(0, 12).join("\n");
    return {
      tool,
      summary: `Write ${args.path} (${content.split("\n").length} lines)`,
      detail: preview + (content.split("\n").length > 12 ? "\n…" : ""),
    };
  }
  if (tool === "edit_file") {
    return {
      tool,
      summary: `Edit ${args.path}`,
      detail: `- ${String(args.old_string ?? "").slice(0, 400)}\n+ ${String(args.new_string ?? "").slice(0, 400)}`,
    };
  }
  return { tool, summary: `Run ${tool}`, detail: JSON.stringify(args).slice(0, 400) };
}

export async function runSubagent(task: string, signal?: AbortSignal): Promise<string> {
  const tools = buildTools({});
  const subTools = new Map([...tools].filter(([, t]) => t.subagentSafe));
  const system = buildSystemPrompt({ tools: subTools, effort: "low", subagent: true });
  const messages: ChatMessage[] = [
    { role: "system", content: system },
    { role: "user", content: task },
  ];
  const { subagent: subagentModel } = effectiveModels();
  const executed = new Set<string>();
  let emptyNudged = false;
  for (let i = 0; i < 8; i++) {
    const res = await chat(messages, { model: subagentModel, signal, enabledTools: [], maxTokens: DEFAULT_MAX_TOKENS });
    const key = (c: { tool: string; args: Record<string, unknown> }) =>
      c.tool + JSON.stringify(c.args);
    const contentCalls = parseToolCalls(res.content);
    const reasoningCalls = res.reasoning ? parseToolCalls(res.reasoning) : [];
    const contentKeys = new Set(contentCalls.map(key));
    const calls = [
      ...contentCalls,
      ...reasoningCalls.filter((c) => !contentKeys.has(key(c)) && !executed.has(key(c))),
    ];
    for (const c of calls) executed.add(key(c));
    messages.push({ role: "assistant", content: res.content });
    if (calls.length === 0) {
      const visible = stripToolBlocks(res.content);
      if (visible) return visible;
      const reasoningText = res.reasoning ? stripToolBlocks(res.reasoning) : "";
      if (!emptyNudged) {
        emptyNudged = true;
        messages.push({
          role: "user",
          content:
            "[continue] Your last message was empty. Emit the next tool block, or state your findings in plain text.",
        });
        continue;
      }
      return reasoningText || "(subagent returned no answer)";
    }
    const results = [];
    for (const call of calls) {
      if (call.tool === "bash" && !isSafeBash(String(call.args.command ?? ""))) {
        results.push({
          tool: call.tool,
          status: "error" as const,
          output: "subagents may only run read-only shell commands",
        });
        continue;
      }
      const r = await executeTool(subTools, call.tool, call.args);
      results.push({ tool: call.tool, ...r });
    }
    messages.push({ role: "user", content: formatToolResults(results) });
  }
  return "(subagent ran out of tool rounds without a final answer)";
}

/** Review whether the goal was achieved. Returns { done, reason }. */
export async function reviewGoal(
  state: AgentState,
  goal: string,
): Promise<{ done: boolean; reason: string }> {
  const transcript = state.messages
    .filter((m) => m.role !== "system")
    .map((m) => `[${m.role}]\n${m.content.slice(0, 3000)}`)
    .join("\n\n")
    .slice(-30_000);

  const res = await chat(
    [
      {
        role: "system",
        content: `You are a goal reviewer. Your job: read the conversation transcript and decide whether the original goal was achieved.

Key principle: match your judgment to the goal's nature. A conversational question ("how can you help?", "what is X?") is met by a relevant, substantive answer — tools are not required. A task goal ("fix the bug", "create a file") requires actual tool results.

Rules:
- If the goal was conversational (a question, greeting, or request for info) and the agent gave a relevant, helpful response, answer YES.
- If the goal required concrete action (file edits, commands, code changes) and every part was accomplished with real tool results, answer YES.
- If the goal required action but any part was skipped, failed, or only described but not executed, answer NO.
- If the agent hit an iteration limit or got stuck on a task goal, answer NO.

Respond with exactly one line: YES: <brief reason> or NO: <brief reason>.`,
      },
      {
        role: "user",
        content: `Goal: ${goal}\n\nTranscript:\n${transcript || "(empty)"}`,
      },
    ],
    { model: effectiveModels().subagent, maxTokens: 512 },
  );

  const text = res.content.trim();
  if (/^\s*YES[:\s]/i.test(text) || /^\s*YES$/i.test(text)) {
    return { done: true, reason: text.replace(/^\s*YES:?\s*/i, "") };
  }
  return { done: false, reason: text.replace(/^\s*NO:?\s*/i, "") || "goal not fully achieved" };
}

export async function runTurn(
  state: AgentState,
  userMessage: string,
  effort: Effort,
  cb: AgentCallbacks,
  signal?: AbortSignal,
): Promise<void> {
  const config = loadConfig();
  const { agent: agentModel } = effectiveModels();

  // Auto-mode: quick pre-check with llama-3.1-8b-instant to decide if
  // write/edit/bash tools are actually needed for this request.
  let autoModeReadOnly = false;
  if (config.auto) {
    try {
      const pre = await chat(
        [
          { role: "system", content: "You decide whether a user's request requires creating/editing files or running commands to satisfy it. If the user is just asking a question, asking for analysis, or requesting an explanation — something that can be fully answered in plain text — answer NO. If they explicitly asked to create, write, edit, build, install, deploy, or run something that would change files or execute commands, answer YES. Answer only YES or NO." },
          { role: "user", content: userMessage.slice(0, 2000) },
        ],
        { model: "llama-3.1-8b-instant", maxTokens: 8, temperature: 0 },
      );
      if (/^\s*no\b/i.test(pre.content.trim())) {
        autoModeReadOnly = true;
        cb.onNotice?.("auto-mode: request looks like a question — answering in-chat (no file writes or commands)");
      }
    } catch (e) {
      // If the pre-check fails, allow tools (fail-open).
      trace("auto.precheck_failed", { error: String(e) });
    }
  }

  const tools = buildTools({
    onSubagent: (task) => runSubagent(task, signal),
    onTodos: cb.onTodos ?? (() => {}),
  });

  // If auto-mode decided no tool use is needed, filter out write/edit/bash.
  const effectiveTools = autoModeReadOnly
    ? new Map([...tools].filter(([, t]) => !t.needsApproval))
    : tools;

  // If tools were filtered, also restrict the agent's system prompt.
  const system = buildSystemPrompt({ tools: effectiveTools, effort });
  const maxIterations = EFFORT_LEVELS[effort].maxIterations;

  state.messages.push({ role: "user", content: userMessage });
  trace("turn.user", { chars: userMessage.length, effort, autoMode: config.auto });
  logger.info("turn.start", { effort, history: state.messages.length, autoMode: config.auto });

  const turnExecuted = new Set<string>();
  let realityNudges = 0;
  let verifyNudges = 0;
  let failureNudges = 0;
  let emptyNudges = 0;
  let guessNudges = 0;
  let lastModifyRound = -1;
  let lastVerifyRound = -1;
  let lastBashFailed = false;

  for (let round = 0; round < maxIterations; round++) {
    if (signal?.aborted) throw new Error("aborted");
    const res = await chat([{ role: "system", content: system }, ...state.messages], {
      model: agentModel,
      signal,
      onDelta: cb.onDelta,
      enabledTools: [],
      maxTokens: DEFAULT_MAX_TOKENS,
    });
    addUsage(state, res.usage);
    cb.onUsage?.(res.usage, res.breakdown ? costFromBreakdown(res.breakdown) : costFromUsage(res.usage));

    // compound surfaces a reasoning channel; the model sometimes "performs"
    // tool calls there and never repeats them in content. Salvage those, but
    // only once per turn — it re-emits the same calls every round.
    const key = (c: { tool: string; args: Record<string, unknown> }) =>
      c.tool + JSON.stringify(c.args);
    const contentCalls = parseToolCalls(res.content);
    const reasoningCalls = res.reasoning ? parseToolCalls(res.reasoning) : [];
    const contentKeys = new Set(contentCalls.map(key));
    const novelReasoningCalls = reasoningCalls.filter(
      (c) => !contentKeys.has(key(c)) && !turnExecuted.has(key(c)),
    );
    const calls = [...contentCalls, ...novelReasoningCalls];
    for (const c of calls) turnExecuted.add(key(c));

    const visible = stripToolBlocks(res.content);
    trace("turn.assistant", { round, chars: res.content.length, tool_calls: calls.length });
    state.messages.push({ role: "assistant", content: res.content });

    if (calls.length === 0) {
      // Stall guard: an empty reply (everything stuck in the reasoning
      // channel) is not an answer. Push the model to continue.
      if (!visible && emptyNudges < 2) {
        emptyNudges++;
        state.messages.push({
          role: "user",
          content:
            "[continue] Your last message was empty. Continue the task: emit the next tool block, or — if you are genuinely done — state your final answer in plain text.",
        });
        trace("turn.empty_nudge", { round });
        logger.warn("turn.empty_nudge", { round });
        continue;
      }
      // Fabrication guard: a "final" answer claiming actions when zero tools
      // ran this turn is invented. Bounce it back (and don't show it).
      if (turnExecuted.size === 0 && realityNudges < 2 && claimsAction(res.content)) {
        realityNudges++;
        state.messages.push({
          role: "user",
          content:
            "[reality check] You executed ZERO tools this turn, so nothing you described actually happened — no files exist, no commands ran. Perform the task for real now using tool blocks (<glint:tool> ... </glint:tool>), one step at a time, and wait for each result.",
        });
        trace("turn.reality_nudge", { round });
        logger.warn("turn.reality_nudge", { round });
        continue;
      }
      // Verification guard: files were modified but nothing was run afterward
      // to prove the change works. Ask for proof.
      if (lastModifyRound !== -1 && lastVerifyRound < lastModifyRound && verifyNudges < 2) {
        verifyNudges++;
        state.messages.push({
          role: "user",
          content:
            "[verification check] You modified files but ran nothing afterward to verify the change. Run the relevant test/build/command now and only then conclude — if it fails, keep fixing. If you genuinely cannot fix it, say so honestly instead of claiming success.",
        });
        trace("turn.verify_nudge", { round });
        logger.warn("turn.verify_nudge", { round });
        continue;
      }
      // Assumption guard: "illustrative"/"typical contents" answers are
      // fabricated file descriptions. Demand reads of the real files.
      if (guessNudges < 2 && looksGuessed(res.content)) {
        guessNudges++;
        state.messages.push({
          role: "user",
          content:
            "[assumption check] Your answer contains GUESSED content (words like 'typical', 'likely', 'illustrative', 'presumably'). That is fabrication. Read the actual files with read_file/ls/grep — every file, field, and behavior you describe must come from a real tool result in this conversation. Rewrite the answer from evidence only, and drop anything you cannot verify.",
        });
        trace("turn.guess_nudge", { round });
        logger.warn("turn.guess_nudge", { round });
        continue;
      }
      // Failure-denial guard: the most recent command FAILED but the final
      // answer claims success anyway.
      if (lastBashFailed && failureNudges < 2 && claimsSuccess(res.content)) {
        failureNudges++;
        state.messages.push({
          role: "user",
          content:
            "[failure check] Your most recent command FAILED — the task is NOT done. Either fix the problem and prove it with a passing run, or state plainly that it is unresolved and why. Do not claim success.",
        });
        trace("turn.failure_nudge", { round });
        logger.warn("turn.failure_nudge", { round });
        continue;
      }
      if (visible) cb.onAssistantText?.(visible);
      if (lastBashFailed && claimsSuccess(res.content)) {
        cb.onNotice?.(
          "⚠ the last command this turn failed, but the summary above claims success — verify before trusting it",
        );
      }
      logger.info("turn.done", { rounds: round + 1 });
      return;
    }

    // Calls pending: show brief narration only. Long mid-round text is a
    // draft answer the model will re-state once results land — hold it, along
    // with premature "I did X" claims.
    if (visible && visible.length <= 240 && !claimsAction(visible)) cb.onAssistantText?.(visible);

    const results: Array<{ tool: string; status: "ok" | "error"; output: string }> = [];
    for (const call of calls) {
      if (signal?.aborted) throw new Error("aborted");
      const spec = tools.get(call.tool);
      let approved = true;
      if (spec?.needsApproval && !config.yolo) {
        const autoSafe = call.tool === "bash" && isSafeBash(String(call.args.command ?? ""));
        if (!autoSafe && cb.onApproval) {
          approved = await cb.onApproval(approvalSummary(call.tool, call.args));
          trace("tool.approval", { tool: call.tool, approved });
        }
      }
      if (!approved) {
        results.push({ tool: call.tool, status: "error", output: "user denied this action" });
        cb.onToolEnd?.(call.tool, "error", "denied by user");
        continue;
      }
      cb.onToolStart?.(call.tool, call.args);
      const result = await executeTool(effectiveTools, call.tool, call.args);
      results.push({ tool: call.tool, ...result });
      cb.onToolEnd?.(call.tool, result.status, result.output);
      if (result.status === "ok" && (call.tool === "write_file" || call.tool === "edit_file")) {
        lastModifyRound = round;
      }
      if (call.tool === "bash") {
        lastBashFailed = result.status === "error";
        if (result.status === "ok") lastVerifyRound = round;
      }
    }
    state.messages.push({ role: "user", content: formatToolResults(results) });
  }

  cb.onNotice?.(
    `Reached the ${effort}-effort limit of ${maxIterations} tool rounds. Say "continue" to keep going, or raise /effort.`,
  );
  logger.warn("turn.max_iterations", { maxIterations });
  trace("turn.max_iterations", { maxIterations });
}

