submitRef.current = submit;

if (phase === "intro") {
  return <Intro onDone={() => setPhase("ready")} />;
}

const cfg = loadConfig();
const thoughtsOn = cfg.thoughts;
const lastThought = thoughtLines.length > 0 ? thoughtLines[thoughtLines.length - 1] : "";
const tpsLabel = `${tpsTrend === "up" ? "↑" : "↓"} ${fmtTok(tps)} tps`;

// Transcript is bottom-anchored: a Spacer above the items pushes them to the
// bottom of the (flex-grow) region, and overflow:hidden clips whatever spills
// off the top. scrollOffset hides items off the bottom so PgUp reveals older
// history. Clamp the offset to the list so it can never strand the view.
const clampedOffset = Math.min(scrollOffset, Math.max(0, items.length - 1));
const visibleItems = clampedOffset > 0 ? items.slice(0, items.length - clampedOffset) : items;

return (
  <Box flexDirection="column" width={termCols} height={termRows}>
    {/* Transcript — fills all space above the footer, newest hugging the
        bottom. justifyContent flex-end pins content to the bottom; when it
        overflows, the excess spills off the TOP and overflow:hidden clips it,
        so the newest line is always visible. PgUp/PgDn scrolls back. */}
    <Box flexGrow={1} flexDirection="column" justifyContent="flex-end" overflow="hidden">
      {visibleItems.map((item) => (
        <ItemView key={item.id} item={item} />
      ))}
    </Box>

    {/* Live region: streaming answer + thought dropdown, just above the
        footer. flexShrink:0 keeps it from being squeezed out. */}
    {running && thoughtsOn && thoughtLines.length > 0 && (
      <Box flexShrink={0} flexDirection="column" borderStyle="round" borderColor={theme.faint} paddingX={1}>
        <Text color={theme.dim}>
          {thoughtExpanded ? "▾" : "▸"} thinking{" "}
          <Text color={theme.faint}>(click or ctrl+t to {thoughtExpanded ? "collapse" : "expand"})</Text>
        </Text>
        {thoughtExpanded ? (
          thoughtLines.slice(-12).map((l, i) => (
            <Text key={i} color={theme.faint} italic>
              {"  "}
              {l.slice(0, 200)}
            </Text>
          ))
        ) : (
          <Text color={theme.faint} italic>
            {"  "}
            {lastThought.slice(-160) || "…"}
          </Text>
        )}
      </Box>
    )}

    {stream ? (
      <Box flexShrink={0} flexDirection="row">
        <Box width={2} flexShrink={0}>
          <Text color={theme.orange}>✦</Text>
        </Box>
        <Box flexDirection="column" flexGrow={1}>
          <Markdown text={stream} />
        </Box>
      </Box>
    ) : null}

    {approval && (
      <Approval
        request={approval.request}
        onDecision={(ok, always) => {
          if (always) loadConfig().yolo = true;
          approval.resolve(ok);
          setApproval(null);
        }}
      />
    )}

    {effortMenu && (
      <Box flexShrink={0} flexDirection="column" borderStyle="round" borderColor={theme.orange} paddingX={1}>
        <Text bold color={theme.orange}>
          effort level <Text color={theme.faint}>(↑/↓ · enter · esc)</Text>
        </Text>
        {EFFORT_OPTIONS.map((o, i) => (
          <Text key={o.value}>
            <Text color={i === effortMenuIdx ? theme.orange : theme.faint}>
              {i === effortMenuIdx ? " ❯ " : "   "}
            </Text>
            <Text bold={i === effortMenuIdx} color={i === effortMenuIdx ? theme.ink : theme.dim}>
              {o.value.padEnd(10)}
            </Text>
            <Text color={theme.faint}> {o.blurb}</Text>
            {o.value === cfg.effort ? <Text color={theme.green}> ← current</Text> : null}
          </Text>
        ))}
      </Box>
    )}

    {todos.length > 0 && (
      <Box flexShrink={0} flexDirection="column" marginLeft={1}>
        {todos.map((t, i) => (
          <Text key={i}>
            {t.status === "done" ? (
              <Text color={theme.orange}>● </Text>
            ) : t.status === "in_progress" ? (
              <Text color={theme.ink}>◐ </Text>
            ) : (
              <Text color={theme.faint}>○ </Text>
            )}
            <Text
              bold={t.status === "in_progress"}
              color={t.status === "in_progress" ? theme.ink : t.status === "done" ? theme.dim : theme.faint}
              strikethrough={t.status === "done"}
            >
              {t.text}
            </Text>
          </Text>
        ))}
      </Box>
    )}

    {running && (
      <Box flexShrink={0}>
        <Text color={theme.orange}>{SPINNER_FRAMES[spin % SPINNER_FRAMES.length]} </Text>
        <Text color={theme.amber}>
          {activeTool
            ? `${activeTool.tool}${activeTool.hint ? ` ${activeTool.hint}` : ""}`
            : `${verbRef.current}…`}
        </Text>
        <Text color={tpsTrend === "up" ? theme.green : theme.red}>
          {"  "}
          {tpsLabel}
        </Text>
        <Text color={theme.faint}>
          {" "}· {elapsed}s · esc to interrupt
        </Text>
      </Box>
    )}

    {/* Goal indicator */}
    {goal && (
      <Box flexShrink={0} marginLeft={1}>
        <Text color={theme.orange}>✦ goal{goalRetries > 0 ? ` (attempt ${goalRetries})` : ""}: </Text>
        <Text color={theme.dim} italic>{goal.slice(0, 120)}</Text>
      </Box>
    )}

    {/* Scroll indicator — shown only while reviewing history. */}
    {clampedOffset > 0 && (
      <Box flexShrink={0} marginLeft={1}>
        <Text color={theme.amber}>⌃ scrolled up · </Text>
        <Text color={theme.faint}>PgDn (or ctrl+f) to return to the latest</Text>
      </Box>
    )}

