useEffect(() => {
  const wantMouse = running && loadConfig().thoughts;
  if (!wantMouse || !stdin) return;
  process.stdout.write("\x1b[?1000h\x1b[?1006h");
  const onData = (data: Buffer) => {
    const s = data.toString("latin1");
    if (/\x1b\[<0;\d+;\d+M/.test(s)) setThoughtExpanded((e) => !e);
  };
