// Row-based scroll. maxScroll = rows of content above the viewport. The
// content box slides under the fixed viewport via marginTop:
//   marginTop = (viewport - content) + scrolledUp
// At scrolledUp=0 the content's bottom aligns to the viewport bottom (newest
// hugging the input bar); when content is shorter than the viewport this is
// positive, pushing the few items down to the bottom. Scrolling up adds rows,
// sliding the content down so earlier rows come into view, until marginTop
// hits 0 (top of history). Refs mirror the values for the input handler.
const maxScroll = Math.max(0, contentRows - viewportRows);
const scrolledUp = Math.min(scrollOffset, maxScroll);
