// One ticker drives spinner, elapsed, tps, AND the throttled stream flush —
// streaming deltas only repaint ~8x/s instead of per-token, which kills the
// layout flicker on fast generations.
useEffect(() => {
  if (!running) return;
  const started = Date.now();
  const t = setInterval(() => {
    setSpin((s) => s + 1);
    setElapsed(Math.floor((Date.now() - started) / 1000));
    setTurnTok(meterRef.current.total());
    setTpsTrend(meterRef.current.trend());
    const visible = visiblePrefix(streamBufRef.current);
    // Cap by *rendered* rows so the live stream never crowds out the footer:
    // wrapped lines count as multiple rows. Keep the tail (newest) only.
    const cols = Math.max(40, termCols - 6);
    const budget = Math.max(4, Math.floor((rowsRef.current - 12) / 2));
    const lines = visible.split("\n");
    const kept: string[] = [];
    let rows = 0;
    for (let i = lines.length - 1; i >= 0 && rows < budget; i--) {
      rows += Math.max(1, Math.ceil(lines[i].length / cols));
      kept.unshift(lines[i]);
    }
    setStream(kept.join("\n"));
  }, 120);
  return () => clearInterval(t);
}, [running, termCols]);

// Measure the transcript after every commit: the content's full height and
// the clipping viewport's height. These drive row-based scrolling — the
// viewport stays fixed while the content slides under it via a negative top
// margin. Guarded setState so re-measuring to the same values is a no-op.
useLayoutEffect(() => {
  const v = viewportElRef.current;
  const c = contentElRef.current;
  if (!v || !c) return;
  const vh = measureElement(v).height;
  const ch = measureElement(c).height;
  if (vh !== viewportRows) setViewportRows(vh);
  if (ch !== contentRows) setContentRows(ch);
});

// Mouse: wheel scrolls the transcript (3 rows per notch); a left-click toggles
// the thought dropdown while thinking is shown. Tracking stays on the whole
// session so the wheel works whether or not a turn is running.
useEffect(() => {
  if (!stdin) return;
  process.stdout.write("\x1b[?1000h\x1b[?1006h");
  const onData = (data: Buffer) => {
    const s = data.toString("latin1");
    const m = s.match(/\x1b\[<(\d+);\d+;\d+M/);
    if (!m) return;
    const btn = Number(m[1]);
    if (btn === 64) {
      // wheel up → scroll back into history
      setScrollOffset((o) => Math.min(maxScrollRef.current, o + 3));
    } else if (btn === 65) {
      // wheel down → toward the latest
      setScrollOffset((o) => Math.max(0, o - 3));
    } else if (btn === 0 && running && loadConfig().thoughts) {
      setThoughtExpanded((e) => !e);
    }
  };
  stdin.on("data", onData);
  return () => {
    stdin.off("data", onData);
    process.stdout.write("\x1b[?1006l\x1b[?1000l");
  };
}, [running, stdin]);

