// Mouse: wheel scrolls the transcript (3 rows per notch); a left-click toggles
// the thought dropdown while thinking is shown. Tracking stays on the whole
// session so the wheel works whether or not a turn is running.
useEffect(() => {
  if (!stdin) return;
  process.stdout.write("\x1b[?1000h\x1b[?1006h");
  const onData = (data: Buffer) => {
    const s = data.toString("latin1");
    const m = s.match(/\x1b\[<(\d+);\d+;\d+M/);
    if (!m) return;
    const btn = Number(m[1]);
    if (btn === 64) {
      // wheel up → scroll back into history
      setScrollOffset((o) => Math.min(maxScrollRef.current, o + 3));
    } else if (btn === 65) {
      // wheel down → toward the latest
      setScrollOffset((o) => Math.max(0, o - 3));
    } else if (btn === 0 && running && loadConfig().thoughts) {
      setThoughtExpanded((e) => !e);
    }
  };
  stdin.on("data", onData);
  return () => {
    stdin.off("data", onData);
    process.stdout.write("\x1b[?1006l\x1b[?1000l");
  };
}, [running, stdin]);

