// Cap by *rendered* rows so the live stream never crowds out the footer:
// wrapped lines count as multiple rows. Keep the tail (newest) only.
const cols = Math.max(40, termCols - 6);
const budget = Math.max(4, Math.floor((rowsRef.current - 12) / 2));
const lines = visible.split("\n");
const kept: string[] = [];
let rows = 0;
for (let i = lines.length - 1; i >= 0 && rows < budget; i--) {
  rows += Math.max(1, Math.ceil(lines[i].length / cols));
  kept.unshift(lines[i]);
}
setStream(kept.join("\n"));

