export async function startApp(opts: { yolo: boolean; intro: boolean; resume?: string }): Promise<void> {
  // Enter the alternate screen buffer so the UI owns a fixed viewport: the
  // input + status bar stay welded to the bottom and output can't scroll the
  // app off the top of the terminal. Restored on exit.
  process.stdout.write("\x1b[?1049h\x1b[2J\x1b[H");
  const instance = render(<App opts={opts} />, { exitOnCtrlC: false });
  try {
    await instance.waitUntilExit();
  } finally {
    process.stdout.write("\x1b[?1006l\x1b[?1000l");
    process.stdout.write("\x1b[?1049l");
  }
}
